import{_ as r,a0 as l,w as a,s,I as u,x as t,a1 as i,A as o,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"如何在Linux Mint 16中正确安装Ubuntu One | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux Mint 16中正确安装Ubuntu One | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux Mint 16中正确安装Ubuntu One | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux Mint 16中正确安装Ubuntu One | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/How To Properly Install Ubuntu One In Linux Mint 16","title":"如何在Linux Mint 16中正确安装Ubuntu One","tag":"201402","desc":""},"relativePath":"201402/How To Properly Install Ubuntu One In Linux Mint 16.md","filePath":"[post].md"}'),d={name:"201402/How To Properly Install Ubuntu One In Linux Mint 16.md"};function b(x,n,m,f,L,O){const e=l("Link");return a(),s("div",null,[n[16]||(n[16]=u("h1",{id:"如何在linux-mint-16中正确安装ubuntu-one",tabindex:"-1"},[t("如何在Linux Mint 16中正确安装Ubuntu One "),u("a",{class:"header-anchor",href:"#如何在linux-mint-16中正确安装ubuntu-one","aria-label":"Permalink to “如何在Linux Mint 16中正确安装Ubuntu One”"},"​")],-1)),n[17]||(n[17]=u("p",null,[u("img",{src:"http://itsfoss.com/wp-content/uploads/2014/01/Ubuntu-One-Linux-Mint.jpg",alt:""})],-1)),u("p",null,[n[1]||(n[1]=t("由于",-1)),i(e,{href:"http://www.linuxmint.com/"},{default:o(()=>[...n[0]||(n[0]=[t("Linux Mint",-1)])]),_:1}),n[2]||(n[2]=t("是基于 Ubuntu 的，所以我认为 Ubuntu One 应该是预装程序之一。不过我错了。我自行从 Software Manager 安装了 Ubuntu One，令我惊讶的是，它居然无法正常运行。在这篇教程中我们会告诉你",-1)),n[3]||(n[3]=u("strong",null,"如何在 Linux Mint 16中安装 Ubuntu One",-1)),n[4]||(n[4]=t(" 以及如何正常运行它。",-1))]),n[18]||(n[18]=p(`<h3 id="在linux-mint-16-中安装-ubuntu-one" tabindex="-1">在Linux Mint 16 中安装 Ubuntu One: <a class="header-anchor" href="#在linux-mint-16-中安装-ubuntu-one" aria-label="Permalink to “在Linux Mint 16 中安装 Ubuntu One:”">​</a></h3><p>当你通过 Software Manager 安装 Ubuntu One 客户端以后，你准备打开并配置它时，你甚至都无法在菜单搜索里面找到它。就像是完全没有安装过一样。但你查看 Software Manager，又显示它已经安装完成了。问题到底出在哪了？</p><p>问题的关键是 <strong>Ubuntu One installer</strong> 需要 <strong>ubuntuone-control-panel-qt</strong> 包。这个包没有安装，你的 Ubuntu One 的安装过程就无法运行。要解决这个问题，打开终端 (Ctrl+Alt+T)并运行下面的命令：</p><pre><code>sudo apt-get install ubuntuone-control-panel-qt
</code></pre><p>现在你在菜单里面搜索，你会发现 Ubuntu One 已经存在了。现在你可以配置账户，选择哪些同步和哪些不同步。现在你可能觉得你已经解决了所有的问题，这时你会发现 <strong>Ubuntu One 指示器并没出现在面板上</strong>。</p><h3 id="在-linux-mint-16-中安装-ubuntu-one-indicator" tabindex="-1">在 Linux Mint 16 中安装 Ubuntu One indicator: <a class="header-anchor" href="#在-linux-mint-16-中安装-ubuntu-one-indicator" aria-label="Permalink to “在 Linux Mint 16 中安装 Ubuntu One indicator:”">​</a></h3><p>你可以通过添加以下的 PPA 在 Linux Mint 中获取 Ubuntu One indicator 程序：</p><pre><code>sudo add-apt-repository ppa:rye/ubuntuone-extras
sudo apt-get update 
sudo apt-get install indicator-ubuntuone
</code></pre><p>注销并重新登录后，你会看到这个指示器已经出现在面板中。与此同时，你的 Ubuntu One 也全部安装完成了。我希望这篇 <strong>在 Linux Mint 中安装 Ubuntu One</strong> 会对你有所帮助。欢迎提出问题和建议。</p><hr>`,10)),u("p",null,[n[6]||(n[6]=t("via: ",-1)),i(e,{href:"http://itsfoss.com/ubuntu-one-linux-mint-16/"},{default:o(()=>[...n[5]||(n[5]=[t("http://itsfoss.com/ubuntu-one-linux-mint-16/",-1)])]),_:1})]),u("p",null,[n[9]||(n[9]=t("译者：",-1)),i(e,{href:"https://github.com/yechunxiao19"},{default:o(()=>[...n[7]||(n[7]=[t("乌龙茶",-1)])]),_:1}),n[10]||(n[10]=t(" 校对：",-1)),i(e,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...n[8]||(n[8]=[t("Caroline",-1)])]),_:1})]),u("p",null,[n[13]||(n[13]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[11]||(n[11]=[t("LCTT",-1)])]),_:1}),n[14]||(n[14]=t(" 原创翻译，",-1)),i(e,{href:"http://linux.cn/"},{default:o(()=>[...n[12]||(n[12]=[t("Linux中国",-1)])]),_:1}),n[15]||(n[15]=t(" 荣誉推出",-1))])])}const g=r(d,[["render",b]]);export{M as __pageData,g as default};
